package com.afaryn.kaoslab.data
import com.afaryn.kaoslab.model.ProductTemplate import kotlinx.coroutines.flow.Flow
interface OwnerRepository { fun getProductTemplates(): Flow<List<ProductTemplate>> suspend fun addProductTemplate(productTemplate: ProductTemplate): Result<String> suspend fun updateProductTemplate(productTemplate: ProductTemplate): Result<Unit> suspend fun deleteProductTemplate(templateId: String): Result<Unit> }

package com.afaryn.kaoslab.data

import com.afaryn.kaoslab.model.ProductTemplate
import com.afaryn.kaoslab.model.SizeOption
import com.google.firebase.firestore.FirebaseFirestore
import com.google.firebase.firestore.Query
import kotlinx.coroutines.channels.awaitClose
import kotlinx.coroutines.flow.Flow
import kotlinx.coroutines.flow.callbackFlow
import kotlinx.coroutines.tasks.await
import javax.inject.Inject
import javax.inject.Singleton

@Singleton
class OwnerRepositoryImpl @Inject constructor(
    private val firestore: FirebaseFirestore
) : OwnerRepository {

    companion object {
        private const val COLLECTION_CUSTOM_PRODUCTS = "customproduct"
    }

    override fun getProductTemplates(): Flow<List<ProductTemplate>> = callbackFlow {
        try {
            val snapshot = firestore.collection(COLLECTION_CUSTOM_PRODUCTS)
                .orderBy("createdAt", Query.Direction.DESCENDING)
                .get()
                .await()

            val templates = snapshot.documents.mapNotNull { document ->
                try {
                    val data = document.data ?: return@mapNotNull null

                    val sizes = (data["sizes"] as? List<Map<String, Any>>)?.map { sizeMap ->
                        SizeOption(
                            label = sizeMap["label"] as? String ?: "",
                            additionalPrice = (sizeMap["additionalPrice"] as? Long)?.toInt() ?: 0
                        )
                    } ?: emptyList()

                    val colors = (data["colors"] as? List<String>) ?: emptyList()

                    ProductTemplate(
                        id = document.id,
                        name = data["name"] as? String ?: "",
                        imageUrl = data["imageUrl"] as? String ?: "",
                        basePrice = (data["basePrice"] as? Long)?.toInt() ?: 0,
                        maxPrice = (data["maxPrice"] as? Long)?.toInt() ?: 0,
                        type = data["type"] as? String ?: "",
                        sizes = sizes,
                        colors = colors,
                        createdAt = data["createdAt"] as? com.google.firebase.Timestamp
                    )
                } catch (e: Exception) {
                    null
                }
            }
            trySend(templates)
            close()
        } catch (e: Exception) {
            close(e)
        }

        awaitClose { }
    }

    override suspend fun addProductTemplate(productTemplate: ProductTemplate): Result<String> {
        return try {
            val document = firestore.collection(COLLECTION_CUSTOM_PRODUCTS)
                .add(productTemplate)
                .await()
            Result.success(document.id)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    override suspend fun updateProductTemplate(productTemplate: ProductTemplate): Result<Unit> {
        return try {
            firestore.collection(COLLECTION_CUSTOM_PRODUCTS)
                .document(productTemplate.id)
                .set(productTemplate)
                .await()
            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }

    override suspend fun deleteProductTemplate(templateId: String): Result<Unit> {
        return try {
            firestore.collection(COLLECTION_CUSTOM_PRODUCTS)
                .document(templateId)
                .delete()
                .await()
            Result.success(Unit)
        } catch (e: Exception) {
            Result.failure(e)
        }
    }
}

package com.afaryn.kaoslab.di

import com.afaryn.kaoslab.data.OwnerRepository
import com.afaryn.kaoslab.data.OwnerRepositoryImpl
import com.google.firebase.firestore.FirebaseFirestore
import dagger.Module
import dagger.Provides
import dagger.hilt.InstallIn
import dagger.hilt.components.SingletonComponent
import javax.inject.Singleton

@Module
@InstallIn(SingletonComponent::class)
object OwnerModule {

    @Provides
    @Singleton
    fun provideOwnerRepository(
        firestore: FirebaseFirestore
    ): OwnerRepository {
        return OwnerRepositoryImpl(firestore)
    }
}

package com.afaryn.kaoslab.ui_owner.my_shop

import android.content.Intent
import android.os.Bundle
import androidx.fragment.app.Fragment
import android.view.LayoutInflater
import android.view.View
import android.view.ViewGroup
import androidx.fragment.app.viewModels
import com.afaryn.kaoslab.R
import com.afaryn.kaoslab.authentication.LoginActivity
import com.afaryn.kaoslab.databinding.FragmentMyShopOwnerBinding
import dagger.hilt.android.AndroidEntryPoint

@AndroidEntryPoint
class MyShopOwnerFragment : Fragment() {
    private var _binding: FragmentMyShopOwnerBinding? = null
    private val binding get() = _binding!!
    private val viewModel: MyShopViewModel by viewModels()

    override fun onCreateView(
        inflater: LayoutInflater, container: ViewGroup?,
        savedInstanceState: Bundle?
    ): View {
        // Inflate the layout for this fragment
        _binding = FragmentMyShopOwnerBinding.inflate(inflater, container, false)
        return binding.root
    }

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        super.onViewCreated(view, savedInstanceState)

        setupToolbar()
    }

    private fun setupToolbar() {
        binding.btnLogout.setOnClickListener {
            viewModel.logOut()
            startActivity(
                Intent(requireContext(), LoginActivity::class.java).apply {
                    flags = Intent.FLAG_ACTIVITY_NEW_TASK or Intent.FLAG_ACTIVITY_CLEAR_TASK
                }
            )
        }
    }

}

